GROUPS=[
 dict(level='pre-a1',id='LEX-PRE-18',title='Reconhecer partes do corpo com cartões',after='FND-04',words=['head','hand','leg','foot'],situation='Quatro cartões bilíngues: cabeça/head, mão/hand, perna/leg, pé/foot. Use desenho de boneco ou só descrições textuais; não pedir que o aluno exponha ou mova partes do corpo. A recebe sequência head–foot; fala Head, please e Foot, please. B seleciona cartões e confirma Head? / Foot?. Troquem com hand–leg. Depois cada personagem fictício aponta uma etiqueta e diz My hand ou My leg com apoio. Mudar posição dos cartões entre rodadas evita acerto só por memória espacial.',result='Rodada A seleciona cabeça e pé, nessa ordem. Rodada B mão e perna. My head/hand/leg/foot identifica parte do personagem. O ouvinte deve confirmar palavra e seleção; não avaliar conhecimento anatômico além dos quatro rótulos.',phon='Ouça head/hand em frases curtas com apoio, depois contraste leg/foot. Se não há voz, fazer leitura e registrar modalidade. Não exigir pronúncia perfeita nem conhecimento de feet para avançar neste pacote.',pitfall='Nenhuma tarefa diagnostica dor ou solicita experiência clínica. O plural feet pode ser reconhecido se surgir, mas não é alvo avaliado. Dividir dois pares em encontros se necessário.'),
 dict(level='pre-a1',id='LEX-PRE-19',title='Pedir uma peça identificada por nome e cor',after='FND-04',words=['coat','hat','socks','jacket'],situation='Cartões com descrição em português e inglês: casaco longo vermelho/red coat; chapéu azul/blue hat; meias brancas/white socks; jaqueta curta preta/black jacket. Quadro das cores permanece visível. A escolhe cartão de pedido, B tem os quatro itens. Use The blue hat, please ou My red coat, please; B repete cor ou objeto e só então entrega cartão. Troquem pedidos, incluindo meias e jaqueta. Não usar tamanhos ou valores novos.',result='Nome e cor precisam coincidir: blue hat não black jacket; white socks não white cup já estudada. Modelo: The black jacket, please. — Jacket? — Yes. Thank you. Socks é bloco plural; não cobrar flexão gramatical não apresentada.',phon='Destinatário restitui objeto e cor antes da entrega. Apoio textual torna tarefa independente de percepção cromática. Ler silenciosamente não é evidência auditiva.',pitfall='Coat/jacket delimitados pelos cartões; não alegar classificação universal de todos os agasalhos. Personagens não precisam vestir peças; escolha não pressupõe gênero ou hábito cultural.'),
 dict(level='a1',id='LEX-A1-13',title='Relatar bem-estar e localizar uma sensação',after='A1-05',words=['stomach','tooth','hurt','feel well'],situation='Cartão Jo: hoje não se sente bem; relata dor na barriga. Cartão Ana: sente-se bem hoje; ontem teve dor num dente, mas a tarefa focaliza hoje. Cartão Lee: mão não dói; pé dói. Apoios: I don’t feel well today; My stomach hurts; My tooth hurts; My hand doesn’t hurt; My foot hurts. A assume personagem e B anota Nome/Bem-estar/Local declarado, usando Is it your hand? = É sua mão? quando precisa esclarecer. Troquem papéis sem dar conselho de saúde.',result='Jo não se sente bem e relata stomach. Ana sente-se bem hoje; não transportar dor passada para presente. Lee foot hurts, hand doesn’t hurt. Os dados são declarações de personagens; não inferir causa, gravidade ou tratamento.',phon='Contraste hurts / doesn’t hurt e hoje/ontem em contexto. O destinatário aponta rótulo escrito da parte do corpo, sem depender de gesto ou contato físico.',pitfall='Não solicitar sintomas reais nem orientar conduta médica. Stomach é localização leiga aqui. Teeth pode ser oferecido como apoio, mas singular tooth é alvo produtivo. Aceitar consulta ao bloco e registrar ajuda.'),
 dict(level='a1',id='LEX-A1-14',title='Receber e encaminhar um recado simples',after='A1-06',words=['message','send','open','close'],situation='Simulação em papel: envelope “Message from Jo: Meet me on Friday, at ten, Room 4”. Tradução de Meet me = encontre-me. A manda B abrir cartão com Open the message, please. B lê dia, hora e sala e confirma. A pede Please send the message to Ana; B move cópia do cartão para caixa Ana, não Lee. Depois Close the message, please significa dobrar cartão, não rasgar nem apagar. Nova rodada: mensagem de Rui para Lee, Monday, at ten, Room 5.',result='Primeira: origem Jo, destinatária Ana, sexta 10h sala 4. Segunda: origem Rui, destinatário Lee, segunda 10h sala 5. Open/read/send/close são ações distintas; pedido de envio não conta como envio até executar movimento do cartão. Close não elimina mensagem.',phon='Destinatário recupera FROM Jo / TO Ana e número da sala. Mantenha conteúdo curto e permita repetição. Sem leitura oral, registrar só recepção escrita e ação.',pitfall='Nenhuma conta real é aberta ou mensagem real enviada. Não exigir domínio de interface tecnológica; cenário de papel verifica língua. Formas de passado não são necessárias para executar comandos.'),
 dict(level='a2',id='LEX-A2-13',title='Ler uma receita e explicar sua sequência',after='A2-05',words=['recipe','ingredient','boil','chop'],situation='Roteiro culinário fictício para ordenar instruções em papel: “Ingredients: water, carrots, rice. Step 1: Chop the carrots. Step 2: Boil the water. Step 3: Add the carrots and rice.” Apoio: add = acrescente; step = etapa. Não é receita completa para execução: não fornece tempo ou proporção. A recebe lista de ingredientes, B recebe passos. Perguntem o que está listado e em qual ordem; depois identifiquem dados que faltam antes de cozinhar. Uma mensagem pede receipt, mas pretendia recipe; reparem a confusão com explicação em português ou inglês simples.',result='Ingredientes listados água, cenoura e arroz. Ordem fornecida: cortar cenouras, ferver água, acrescentar itens. Recipe é roteiro culinário; receipt comprovante. Modelo: Rice is an ingredient. First, chop the carrots; then boil the water. We still need quantities and cooking times. Não executar preparo com instrução incompleta.',phon='Compare recipe/receipt com modelo oral disponível e frase completa. O colega identifica documento pela finalidade e confirma a escolha; não avaliar só discriminação de palavra isolada.',pitfall='Atividade escrita, sem faca ou calor. Não inferir restrição alimentar satisfeita só pela lista curta. Add, first, then e quantities são apoios fornecidos, não entradas novas plenamente desenvolvidas.'),
 dict(level='a2',id='LEX-A2-14',title='Separar previsão do tempo e relato de ocorrência',after='A2-02',words=['windy','storm','forecast','wet'],situation='Cartão A: previsão publicada sexta diz “It may be windy on Saturday. There may be a storm.” Cartão B: relato de sábado à tarde diz “It was windy this morning. The benches are wet. I don’t know whether there was a storm.” Grupo tem encontro interno confirmado às 15h; nada no cartão muda horário. Comparem previsão e observação, avisem o grupo e peçam confirmação de informação ausente. Apoio: benches = bancos; whether = se; forecast = previsão.',result='Sexta previa possibilidade de vento/tempestade; sábado observou vento e bancos molhados. Tempestade não confirmada por esse relato. The forecast mentioned a possible storm. It was windy this morning, and the benches are wet. The indoor meeting is still at three. Não inventar causa de umidade nem cancelamento.',phon='Ouça may be / was e restitua possibilidade versus observação. Marcar sexta/sábado antes de escrever síntese reduz confusão temporal.',pitfall='Cenário não fornece orientação de segurança meteorológica nem pede previsão real. Wet não prova chuva; encontro interno confirmado não implica avaliação de segurança de todo trajeto.'),
 dict(level='b1',id='LEX-B1-13',title='Organizar entrega e usar retorno para revisar',after='B1-01',words=['assignment','hand in','feedback','concentrate'],situation='Cartão aluno: assignment de 300 palavras, rascunho completo, entrega até sexta; feedback recebido pede esclarecer conclusão, ainda não revisada. Relata dificuldade de concentrar-se na sala barulhenta. Cartão colega: sala quieta disponível quinta às 14h, mas reserva precisa ser feita; não pode escrever tarefa por ele. Negociem encontro para revisar e redijam atualização de 80–110 palavras separando rascunho, revisão e entrega. Não definir duração universal de aprendizagem.',result='The assignment has been drafted, not handed in. The feedback asks for a clearer conclusion. The student says a quieter room helps concentration; quinta 14h é disponibilidade, não reserva confirmada. We could revise on Thursday, provided we book the room. I’ll hand it in by Friday. Promessa de entrega ainda não é evento.',phon='Contraste HAND IT IN / REVISE IT e by Friday / on Thursday. O parceiro recupera ação e prazo antes de sugerir plano.',pitfall='Feedback não equivale a nota ou aprovação. Assignment é tarefa, não diploma. Não atribuir dificuldade de concentração a diagnóstico; relato situado. Orientações de conteúdo não são autorização para outro escrever a produção do aluno.'),
 dict(level='b1',id='LEX-B1-14',title='Relatar uma partida sem inventar o resultado',after='B1-02',words=['match','score','team','take part'],situation='Fonte A: 12 pessoas se inscreveram em torneio local; oito participaram. Jo jogou pela equipe Azul; Lee assistiu. Partida mudou de sábado para domingo. Fonte B: mensagem do intervalo informa Azul 1, Verde 0; resultado final não chegou. A prepara recado para amigo; B confere quem jogou, quem assistiu e qual placar é conhecido. Depois recebam atualização fictícia: final Azul 1, Verde 2. Reescrevam resultado sem apagar que o primeiro dado era parcial.',result='Eight of twelve registered participants took part. Jo played for the Blue team; Lee watched. The match took place on Sunday. At half-time the score was one–nil to Blue; final inicialmente desconhecido. Após atualização, Green won two–one. Não anunciar vitória de Azul a partir do intervalo.',phon='Distinguir one–nil / one–two com nomes das equipes. Aceitar zero em vez de nil; o ouvinte precisa registrar quem tinha cada número.',pitfall='Esporte escolhido é ficcional e não exige conhecer regras além dos dados. One–two e two–one precisam de orientação por equipe. Apoiar won e half-time com tradução; não contar vocabulário incidental como inventário concluído.'),
 dict(level='b2',id='LEX-B2-15',title='Negociar carga de trabalho e delegação',after='B2-04',words=['workload','negotiate','compromise','delegate'],situation='Equipe fictícia tem duas pessoas e seis relatórios, prazo sexta. Jo propõe negociar prazo; cliente aceita receber quatro relatórios sexta e dois segunda. Lee pode revisar dois, mas Jo mantém aprovação final. A representa Jo, B cliente ou Lee. Negociem escopo, prazo e responsabilidade; escrevam acordo distinguindo concessão aceita de proposta ainda aberta. No cartão alternativo, cliente ainda não respondeu: não reutilizar linguagem de acordo alcançado.',result='The workload exceeds the original allocation in the scenario. They negotiated and reached a compromise: four reports Friday, two Monday. Jo delegated two reviews to Lee but kept final approval. Cartão alternativo: We are trying to negotiate; no compromise has been agreed yet. Delegação não significa conclusão das revisões nem transferência automática de toda responsabilidade.',phon='Marque FOUR on Friday / TWO on Monday e REVIEW / FINAL APPROVAL. O parceiro devolve distribuição exata antes de fechar o acordo.',pitfall='Não traduzir compromise por compromisso em todo contexto. O pacote não aconselha gestão real de pessoal; avalia clareza da negociação fictícia. Aceitar proposta diferente se dados e aceites forem atualizados explicitamente.'),
 dict(level='b2',id='LEX-B2-16',title='Sintetizar relatos ambientais com alcance limitado',after='B2-06',words=['drought','flood','habitat','conserve'],situation='Boletim fictício A informa seca prolongada na região Norte; não traz medidas de intensidade nem causa. Boletim B informa inundação na região Sul ontem, estrada fechada naquele momento; situação atual desconhecida. Uma campanha visa conservar água e outra proposta visa proteger habitat, mas não há medição de efeitos nem execução confirmada da proposta. A prepara síntese; B rejeita mensagem que mistura regiões e afirma sucesso das campanhas. Produzam versão com lugares, tempos e limites.',result='The northern report describes a prolonged drought. The southern report describes a flood yesterday; current road access needs checking. The campaign encourages people to conserve water, but no reduction is measured. The proposal aims to protect habitat; implementation is unconfirmed. Não tratar seca e inundação como mesmo evento ou inferir causa global a partir dos cartões.',phon='Destaque NORTH / SOUTH, YESTERDAY / NOW UNKNOWN e AIMS TO / HAS DONE. Destinatário organiza tabela de fonte, ocorrência e estado.',pitfall='Os boletins são ficção de ensino, não aconselhamento ambiental ou alerta real. Nenhuma espécie, causa ou estimativa climática externa foi inventada. Nomear fenômeno não comprova seu mecanismo.'),
 dict(level='c1',id='LEX-C1-09',title='Comparar interpretações críticas de uma narrativa',after='B2-05',words=['poignant','contrived','allusion','satire'],situation='Microficção autoral: “Every form required a second form confirming that the first form existed. Mara waited with the coat her father had left behind. At closing time, a stranger appeared with exactly the missing document.” Crítico A vê sátira da burocracia e acha o casaco comovente. Crítico B acha o aparecimento do estranho forçado. Um terceiro sugere alusão a outra história, mas não identifica fonte. Compare leituras em 140–180 palavras, cite os detalhes do texto e explique quais interpretações são apoiadas e quais permanecem abertas. Não buscar obra externa para inventar referência.',result='Repeated forms support a satirical reading. The coat can make the scene poignant for a reader, but reaction is not universal. The convenient stranger may be judged contrived; atribuir avaliação, não afirmar desonestidade autoral. The proposed allusion remains unsubstantiated without an identifiable source. Leituras podem coexistir; emoção e crítica da construção não se excluem.',phon='Leia o trecho em versões neutra e irônica; interlocutor distingue pista textual de efeito acrescentado pela leitura. Explicar com paráfrase antes de exigir produção dos termos críticos.',pitfall='Não impor leitura única nem afirmar que autor real pretendeu algo; texto autoral fictício do exercício. Allusion é referência possível, não autorização para fabricar influência literária. Evitar equivalência entre satire e qualquer humor.'),
 dict(level='c1',id='LEX-C1-10',title='Comparar anúncio de moradia e relatos de uso',after='B2-04',words=['cramped','well-maintained','soundproof','disruption'],situation='Anúncio fictício descreve sala como well-maintained e soundproof. Visita de dez minutos ocorreu sem atividades nas salas vizinhas; paredes pareciam conservadas, nenhum laudo apresentado. Dois usuários relatam espaço cramped com seis pessoas e equipamentos; para encontros individuais, um deles achou adequado. Ambos relataram disruption durante obra de manhã. Outros usuários não responderam. A sintetiza anúncio e relatos; B precisa decidir quais esclarecimentos pedir, sem solicitar conclusão técnica de acústica ou segurança.',result='The listing claims soundproofing, but the short quiet visit does not establish it. The room appears well-maintained; no inspection report is available. Two users found it cramped for six people with equipment, not for every possible use. They reported disruption during morning works; effects on non-respondents are unknown. Pedir condições de uso e evidência pertinente, sem emitir certificação.',phon='Separar LISTING CLAIMS / USERS REPORT / WE OBSERVED por pausas e atribuição. O ouvinte reconstrói origem e alcance antes de resumir.',pitfall='Ensino de leitura crítica e registro; não laudo imobiliário nem jurídico. Soundproof em anúncio é alegação forte; não tratar quiet moment como comprovação. Disruption não implica paralisação total sem dados.')
]
